<div class="two-col menus-layout"><section><div class="panel"><div class="panel-head"><div><h2>Create menu</h2><p>Assign a menu to the primary or footer location.</p></div></div><form method="post" action="/admin/menus"><?= csrf_field() ?><div class="field"><label>Name</label><input name="name" required placeholder="Primary navigation"></div><div class="field"><label>Location</label><select name="location"><option value="">Unassigned</option><option value="primary">Primary</option><option value="footer">Footer</option></select></div><button class="btn primary" type="submit">Create menu</button></form></div><br><div class="panel"><h3>Menus</h3><div class="menu-list"><?php foreach($menus as $m):?><a class="<?= (int)$m['id']===$selected?'active':'' ?>" href="/admin/menus?menu=<?= (int)$m['id'] ?>"><strong><?= e($m['name']) ?></strong><span><?= e($m['location']??'Unassigned') ?></span></a><?php endforeach;?></div></div></section><section class="panel"><?php if($selected):?><div class="panel-head"><div><h2>Menu items</h2><p>Lower sort numbers appear first.</p></div></div><form class="menu-add" method="post" action="/admin/menus/<?= (int)$selected ?>/items"><?= csrf_field() ?><div class="field"><label>Label</label><input name="label" required></div><div class="field"><label>URL</label><input name="url" required placeholder="/about or https://…" list="page-links"><datalist id="page-links"><?php foreach($pages as $p):?><option value="/<?= e($p['slug']) ?>"><?= e($p['title']) ?></option><?php endforeach;?><option value="/blog">Blog</option></datalist></div><div class="row-fields"><div class="field"><label>Sort</label><input name="sort_order" type="number" value="0"></div><div class="field"><label>Target</label><select name="target"><option value="_self">Same tab</option><option value="_blank">New tab</option></select></div></div><button class="btn primary" type="submit">Add item</button></form><div class="sortable-list"><?php foreach($items as $it):?><div class="menu-item-row"><span class="drag">⋮⋮</span><div><strong><?= e($it['label']) ?></strong><small><?= e($it['url']) ?> · order <?= (int)$it['sort_order'] ?></small></div><form method="post" action="/admin/menu-items/<?= (int)$it['id'] ?>/delete" data-confirm="Remove this menu item?"><?= csrf_field() ?><button class="btn small danger" type="submit">Remove</button></form></div><?php endforeach;?><?php if(!$items):?><p class="muted">This menu has no items yet.</p><?php endif;?></div><?php else:?><div class="empty-state"><strong>Create a menu first</strong><p>Then add links and assign it to a theme location.</p></div><?php endif;?></section></div>